    a = list(map(int, data_lines[1].split()))

    def f(x):
        while x % k == 0:
            x //= k
        return x

    # Precompute f for potential sums
    max_sum = 2000
    f_table = [f(x) for x in range(max_sum + 1)]

    # We'll use a recursive backtracking approach
    # State: tuple of remaining numbers on blackboard (sorted)
    # Goal: reach [1]

    def get_possible_sums(indices):
        """Generate all possible f(x+y) where x, y are from the given indices"""
