            sum_val = a[indices[0]] + a[indices[i]]
            results.append((sum_val, i, indices[0]))
            # Continue combining index 0 with others
            if i < len(indices):
                # Actually, we need all pairs
        # Better approach: all pairs from indices
        results = []
        for i in range(len(indices)):
            for j in range(i + 1, len(indices)):
                sum_val = a[indices[i]] + a[indices[j]]
                s = f_table[sum_val]
                results.append((s, indices[i], indices[j]))
        return results

    # Backtracking with memoization
    # State represented by sorted tuple of remaining numbers
    from functools import lru_cache

    def dfs(nums):
        if len(nums) == 1:
            return nums[0] == 1

        @lru_cache(None)
        def indexed_dfs(sorted_nums_tuple):
            n_count = len(sorted_nums_tuple)
            if n_count == 1:
                return sorted_nums_tuple[0] == 1

            # Try all pairs
            for i in range(n_count):
                for j in range(i + 1, n_count):
                    x, y = sorted_nums_tuple[i], sorted_nums_tuple[j]
                    result = f(x + y)
                    new_nums = list(sorted_nums_tuple)
                    new_nums.pop(j)
                    new_nums.pop(i)
                    new_nums.append(result)
                    ns = tuple(sorted(new_nums))

                    if indexed_dfs(ns):
                        return ns[0] == 1
            return False

        return indexed_dfs(tuple(sorted(nums)))

    def dfs_with_path(nums):
        """DFS that returns (possible, [op1, op2, ...]) or (False, None)"""
        @lru_cache(None)
        def _path_dfs(nums_tuple):
            if len(nums_tuple) == 1:
                return nums_tuple[0] == 1, []

            orig = list(nums_tuple)
            n_count = len(orig)

            for i in range(n_count):
                for j in range(i + 1, n_count):
                    x, y = orig[i], orig[j]
                    result = f(x + y)
                    new_nums = orig[:i] + orig[i+1:j] + orig[j+1:] + [result]
                    new_nums.sort()
                    ns = tuple(new_nums)

                    if _path_dfs(ns):
                        # Found a path, return the operation
                        return True, [(x, y, result)]
            return False, None

        possible, path = _path_dfs(tuple(sorted(nums)))
        if possible:
            return "YES\n" + "\n".join(f"{x} {y}" for x, y, _ in path)
        return "NO"

