def solution(input_str):
    n, r = map(int, input_str.split())

    def delta(p1, p2):
        return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2

    def calc_score(config):
        s = 0
        m = len(config)
        for i in range(m):
            for j in range(i+1, m):
                s += delta(config[i], config[j])
        return s

    # Generate all integer points within distance r
    all_points = []
    for x in range(-r, r+1):
        for y in range(-r, r+1):
            if x*x + y*y <= r*r:
                all_points.append((x, y))

    # Unique points sorted by distance from origin (descending)
    unique = sorted(set(all_points), key=lambda p: p[0]**2 + p[1]**2, reverse=True)

    # Filter to only points with distance exactly r (the outer ring)
    max_dist_sq = r * r
    outer_points = [p for p in unique if p[0]**2 + p[1]**2 <= max_dist_sq and p[0]**2 + p[1]**2 == max_dist_sq]

    # Try combinations using only outer ring
    # For reconstruction done from the first 80 points (subset of outer points in practice)
    test_candidates = outer_points[:min(len(outer_points), 200)]

    max_score = 0
    best_config = None

    if not test_candidates:
        # If no points at distance r, use all available points
        test_candidates = unique[:min(200, len(unique))]

    # If we can't use all n points from test_candidates, we must use candidates with repetition
    # Try positions as (i) takes up 4, (ii) takes up 1 point per tower, etc.

    if n > 0:
        if len(test_candidates) >= n:
            for config in itertools.combinations(test_candidates, n):
                score = calc_score(config)
                if score > max_score:
                    max_score = score
                    best_config = list(config)
        else:
            # Must use repetition
            for config in itertools.product(test_candidates[:20], repeat=n):
                score = calc_score(config)
                if score > max_score:
                    max_score = score
                    best_config = list(config)

    # Format and return
    result = [str(max_score)]
    for pt in best_config:
        result.append(f"{pt[0]} {pt[1]}")

    return '\n'.join(result) + '\n'

