def count_box(target, chocolates):
    if target <= 0:
        return 1 if target == 0 else 0
    if not chocolates:
        return 0
    dp = [0] * (target + 1)
    dp[0] = 1
    for s in range(1, target + 1):
        for c in chocolates:
            if c <= s:
                dp[s] = (dp[s] + dp[s - c]) % MOD
    return dp[target]

def solve_with_dp(N, petals, chocolates):
    from collections import defaultdict
    flower_dp = defaultdict(int)
    flower_dp[0] = 1
    for _ in range(N):
        new_flower_dp = defaultdict(int)
        for s, cnt in flower_dp.items():
            for p in petals:
                new_flower_dp[s + p] = (new_flower_dp[s + p] + cnt) % MOD
        flower_dp = new_flower_dp
    if not flower_dp:
        return 0
    max_s = max(flower_dp.keys())
    box_dp = [0] * (max_s + 1)
    box_dp[0] = 1
    for s in range(1, max_s + 1):
        for c in chocolates:
            if c <= s:
                box_dp[s] = (box_dp[s] + box_dp[s - c]) % MOD
    result = 0
    for s, cnt in flower_dp.items():
        result = (result + cnt * box_dp[s]) % MOD
    return result

