    if not lines:
        return '1 2 3 4'

    n, m = int(lines[0]), int(lines[1])

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    idx = 2
    for _ in range(m):
        u, v = int(lines[idx]), int(lines[idx+1])
        idx += 2
        adj[u].append(v)

    # BFS from each node to compute all pairs shortest paths
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        d = [float('inf')] * (n + 1)
        d[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if d[v] == float('inf'):
                    d[v] = d[u] + 1
                    q.append(v)
        for i in range(1, n + 1):
            dist[start][i] = d[i]

    # DP approach to find best path of length 3 (4 cities)
    # dp2[(start, u)] = (v, max_distance) for paths start->...->u->v
    # This tracks the max distance for paths of exactly k edges ending at node v

    # Step 1: All paths of 1 edge (start -> u)
    best1 = []  # Just store valid start nodes

    # Step 2: Build paths of 2 edges (start -> a -> b)
    dp2 = {}  # (start, b) -> (a, max_dist)
    for start in range(1, n + 1):
        for u in range(1, n + 1):
            if dist[start][u] == float('inf'):
                continue
            for v in adj[u]:
                if v == start:
                    continue
                if dist[u][v] == float('inf'):
                    continue
                d = dist[start][u] + dist[u][v]
                if (start, v) not in dp2 or d > dp2[(start, v)][1]:
                    dp2[(start, v)] = (u, d)

    # Step 3: Build paths of 3 edges (start -> a -> b -> c)
    dp3 = {}  # (start, c) -> (b, max_dist)
    parent2 = {}  # (start, c) -> u (the a node in start->a->b->c)

    for start in range(1, n + 1):
        for v in range(1, n + 1):
            if dist[start][v] == float('inf'):
                continue
            key = (start, v)
            if key not in dp2:
                continue

            u, d2 = dp2[key]
            for w in adj[u]:
                if w == start or w == v:
                    continue
                if dist[v][w] == float('inf'):
                    continue

                d3 = d2 + dist[v][w]
                if (start, w) not in dp3 or d3 > dp3[(start, w)]:
                    dp3[(start, w)] = d3
                    parent2[(start, w)] = u

    # Find optimal
    max_total = -1
    best = [1, 2, 3, 4]

    for start in range(1, n + 1):
        for w in range(1, n + 1):
            if start == w:
                continue
            if (start, w) in dp3:
                d = dp3[(start, w)]
                if d > max_total:
                    max_total = d
                    u = parent2[(start, w)]
                    # Find b: we need start->a->b->c where c=w
                    # parent2 holds u (which is a)
                    # Need to find which node is v (b) such that start->u->v->w
                    for v in adj[u]:
                        if v == start or v == w:
                            continue
                        if dist[u][v] < float('inf') and dist[v][w] < float('inf'):
                            best = [start, u, v, w]
                            break

    return ' '.join(map(str, best))

