        current: current planet position
        depth: how many planets have been visited so far
        visited: set of visited planets
        """
        if depth == k:
            return 1

        count = 0
        # We can move to any unvisited planet in [1, current + m]
        for nxt in range(1, min(n, current + m) + 1):
            if nxt not in visited:
                visited.add(nxt)
                count = (count + dfs(nxt, depth + 1, visited)) % MOD
                visited.remove(nxt)
        return count

    total = 0
    # Try each planet as starting point
    for start in range(1, n + 1):
        total = (total + dfs(start, 1, {start})) % MOD

    return str(total)

